import { test, expect } from '@playwright/test';

test.describe('Deep Links Navigation', () => {
  const baseURL = 'http://localhost:3000';

  test.beforeEach(async ({ page }) => {
    await page.goto(baseURL);
  });

  test('should load home page when accessing root URL', async ({ page }) => {
    await page.goto(`${baseURL}/`);
    await expect(page).toHaveURL(`${baseURL}/`);
    await expect(page.getByRole('heading', { name: /home/i })).toBeVisible();
  });

  test('should load products page directly via deep link', async ({ page }) => {
    await page.goto(`${baseURL}/products`);
    await expect(page).toHaveURL(`${baseURL}/products`);
    await expect(page.getByRole('heading', { name: /products/i })).toBeVisible();
    await expect(page.getByRole('link', { name: /products/i })).toHaveClass(/active/);
  });

  test('should load product details page with ID parameter', async ({ page }) => {
    const productId = '123';
    await page.goto(`${baseURL}/products/${productId}`);
    await expect(page).toHaveURL(`${baseURL}/products/${productId}`);
    await expect(page.getByRole('heading', { name: /product details/i })).toBeVisible();
    await expect(page.getByText(new RegExp(`Product ID: ${productId}`))).toBeVisible();
  });

  test('should load about page directly via deep link', async ({ page }) => {
    await page.goto(`${baseURL}/about`);
    await expect(page).toHaveURL(`${baseURL}/about`);
    await expect(page.getByRole('heading', { name: /about/i })).toBeVisible();
  });

  test('should load contact page with query parameters', async ({ page }) => {
    const email = 'test@example.com';
    await page.goto(`${baseURL}/contact?email=${encodeURIComponent(email)}`);
    await expect(page).toHaveURL(new RegExp(`/contact\\?email=${encodeURIComponent(email)}`));
    await expect(page.getByRole('heading', { name: /contact/i })).toBeVisible();
    await expect(page.getByLabel(/email/i)).toHaveValue(email);
  });

  test('should maintain page state when accessing deep link', async ({ page }) => {
    await page.goto(`${baseURL}/dashboard`);
    await expect(page).toHaveURL(`${baseURL}/dashboard`);
    await expect(page.getByRole('heading', { name: /dashboard/i })).toBeVisible();
    const userGreeting = page.getByText(/welcome/i);
    await expect(userGreeting).toBeVisible();
  });

  test('should handle nested route deep links', async ({ page }) => {
    await page.goto(`${baseURL}/settings/profile`);
    await expect(page).toHaveURL(`${baseURL}/settings/profile`);
    await expect(page.getByRole('heading', { name: /profile settings/i })).toBeVisible();
  });

  test('should redirect invalid deep links to home page', async ({ page }) => {
    await page.goto(`${baseURL}/invalid-page-that-does-not-exist`);
    await expect(page).toHaveURL(`${baseURL}/`);
    await expect(page.getByRole('heading', { name: /home/i })).toBeVisible();
  });
});
